const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const cambodia = ee.FeatureCollection('USDOS/LSIB_SIMPLE/2017')
    .filter(ee.Filter.eq('country_na', 'Cambodia'))
    .geometry();

  // 2. Data Acquisition for February (2014-2017)
  const febCol = ee.ImageCollection('MODIS/006/MOD14A1')
    .filter(ee.Filter.calendarRange(2014, 2017, 'year'))
    .filter(ee.Filter.calendarRange(2, 2, 'month'))
    .select('FireMask');

  const febSize = febCol.size().getInfo();
  console.log('February Images:', febSize);

  if (febSize === 0) {
    console.log('No data for February 2014-2017.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Data Acquisition for October (2014-2017)
  const octCol = ee.ImageCollection('MODIS/006/MOD14A1')
    .filter(ee.Filter.calendarRange(2014, 2017, 'year'))
    .filter(ee.Filter.calendarRange(10, 10, 'month'))
    .select('FireMask');

  const octSize = octCol.size().getInfo();
  console.log('October Images:', octSize);

  if (octSize === 0) {
    console.log('No data for October 2014-2017.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 4. Processing - Count fire pixels (FireMask > 0 indicates fire)
  const countFires = function(collection) {
    const fireImage = collection.map(function(img) {
      return img.gt(0);
    }).sum();

    const stats = fireImage.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: cambodia,
      scale: 1000,
      maxPixels: 1e9
    });

    return stats.get('FireMask');
  };

  const febFires = countFires(febCol).getInfo();
  const octFires = countFires(octCol).getInfo();

  console.log('February Fire Detections:', febFires);
  console.log('October Fire Detections:', octFires);

  // 5. Validation & Final Answer
  if (febFires === null || octFires === null) {
    console.log('Calculation failed - null result');
    console.log('<answer>C3</answer>');
    return;
  }

  if (febFires === 0 && octFires === 0) {
    console.log('Valid result: No fires detected in either period');
    console.log('<answer>B</answer>');
    return;
  }

  console.log('Comparison: Feb=' + febFires + ' vs Oct=' + octFires);

  if (febFires > octFires) {
    console.log('February had more active fires than October');
    console.log('<answer>A</answer>');
  } else {
    console.log('February did not have more active fires than October');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
